    max_overlap = 0
    for T_prime in F_star:
        if T != T_prime:
            overlap = len(T.intersection(T_prime))
            if overlap > max_overlap:
                max_overlap = overlap
    return len(T) / max_overlap

def generate_random_hypergraph(v, k):
    vertices = list(range(1, v + 1))
    hyperedges = list(combinations(vertices, k))
    random.shuffle(hyperedges)
    return set(hyperedges[:k])

